"""Deterministic V9.19 numerical figures, 600-dpi RGB TIFFs. No map redraws."""
from pathlib import Path
import csv,json,textwrap
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
from PIL import Image
P=Path(__file__).resolve().parent
D=json.loads((P/'US919_Results.json').read_text()); c=D['target']; t=D['target_detail']['transport'];r=D['target_detail']['full'];w=D['target_detail']['agricultural']; b=D['baseline'];cases=D['cases'];refs=D['references']; strong=next(x for x in cases if x['case']=='strong progress');
plt.rcParams.update({'font.family':'DejaVu Sans','font.size':10,'axes.spines.top':False,'axes.spines.right':False,'axes.labelsize':10,'axes.titlesize':12,'figure.dpi':110})
C='#197b77';O='#bb8847';G='#8793a0';B='#20445d'
def read(n):
 with (P/n).open() as f:return list(csv.DictReader(f))
def save(fig,n):
 p=P/('V919_'+n+'.tif');fig.savefig(p,dpi=600,format='tiff',pil_kwargs={'compression':'tiff_lzw'},facecolor='white');plt.close(fig)
 with Image.open(p) as im:rgb=im.convert('RGB')
 rgb.save(p,dpi=(600,600),compression='tiff_lzw')
def barh(ax,labs,vals,xlabel,title,color=C,fmt='.2f'):
 y=np.arange(len(labs));ax.barh(y,vals,color=color);ax.set_yticks(y,labs);ax.invert_yaxis();ax.set_xlabel(xlabel);ax.grid(axis='x',alpha=.2);ax.set_axisbelow(True);ax.set_title(title,loc='left',fontweight='bold');mx=max(abs(float(v)) for v in vals) or 1;lo=min(0,min(vals));hi=max(0,max(vals));ax.set_xlim(lo-mx*.24 if lo<0 else 0,hi+mx*.25)
 for i,v in enumerate(vals):ax.text(v+mx*.022 if v>=0 else v-mx*.022,i,format(v,fmt),va='center',ha='left' if v>=0 else 'right',fontsize=9)
fig,(ax,bx)=plt.subplots(1,2,figsize=(11,6),layout='constrained');labels=['AEO: BEV + power sensitivity','AEO: matched BEV cost','AEO: fixed reference','Target: full crop floor','Strong cost target','Low petroleum price','Late-2025 petroleum','130% petroleum price','Higher petroleum price','Reference-cost pathway'];vals=[c['aeo_electricity_pass_bn'],c['aeo_bev_matched_bn'],refs[0]['ref_cost_bn'],c['combined_cost_bn'],strong['combined_cost_bn'],refs[3]['ref_cost_bn'],refs[1]['ref_cost_bn'],refs[4]['ref_cost_bn'],refs[2]['ref_cost_bn'],b['combined_cost_bn']];barh(ax,labels,vals,'US$ billion/year','A. Conditional expenditure',[G,G,G,C,C,O,O,O,O,B],'.1f');barh(bx,['Continued petroleum','AEO2026 partial','Target transport','Target after gas use'],[refs[1]['ref_emissions_mt']/1000,refs[0]['ref_emissions_mt']/1000,c['transport_emissions_mt']/1000,(c['transport_emissions_mt']-c['gas_credit_mt'])/1000],'Gt CO₂e/year','B. Partial transport emissions',[O,G,C,C],'.3f');fig.suptitle('2050 national screen: cost-competitive deployment targets',fontweight='bold',fontsize=14);save(fig,'Figure_1')
fig,ax=plt.subplots(figsize=(9,6.5),layout='constrained');barh(ax,[textwrap.fill(x['name'],39) for x in t['selected']],[x['selected_mt'] for x in t['selected']],'Selected dry biomass (Mt/year)','Target residue selection — V9.19');ax.set_title('Target residue selection — V9.19\nFull collection floor; individual category assumptions remain unverified',loc='left',fontsize=11,fontweight='bold');save(fig,'Figure_2')
fig,(ax,bx)=plt.subplots(1,2,figsize=(9,4.5),layout='constrained');labs=['N','P','K'];imports=[t[f'{e.lower()}_imports_kt'] for e in labs];water=[t[f'{e.lower()}_water_kt'] for e in labs];char=[t[f'{e.lower()}_char_kt'] for e in labs];ax.bar(labs,imports,color=O,label='External input');ax.bar(labs,water,bottom=imports,color=C,label='Available aqueous');ax.bar(labs,char,bottom=np.array(imports)+water,color=G,label='Available char nutrients');ax.set_ylabel('Elemental kt/year');ax.set_title('A. Nutrient closure',loc='left',fontweight='bold');ax.legend(fontsize=8);barh(bx,['Stable-C required','Cover crop supplied','Assumed land ceiling'],[t['stable_soil_c_need_mt'],t['cover_crop_stable_c_mt'],10],'Mt stable-equivalent C/year','B. Soil-carbon screen');save(fig,'Figure_3')
sel=[x for x in cases if x['case'] not in ('reference costs','no BEV cost advantage','no tech cost progress')];fig,(ax,bx)=plt.subplots(1,2,figsize=(11,5.7),layout='constrained');labels=[textwrap.fill(x['case'].capitalize(),29) for x in sel];barh(ax,labels,[x['savings_low_petroleum_bn'] for x in sel],'US$ billion/year','A. Saving vs lowest petroleum price');barh(bx,labels,[x['combined_avoided_mt']/1000 for x in sel],'Gt CO₂e/year','B. Integrated abatement',fmt='.3f');save(fig,'Figure_5')
fig,(ax,bx)=plt.subplots(1,2,figsize=(10,5),layout='constrained');barh(ax,['Pyrolysis H₂','Direct vehicle H₂','HTL H₂','PBTL H₂','HEFA H₂'],[r['h2_mt'][k] for k in ['pyrolysis','direct_vehicles','htl','pbtl','hefa']],'Mt H₂/year','A. Hydrogen production and uses');barh(bx,['Reactor electricity','Process steam','HTSE steam/drying','Food heat','Losses/reject'],[r['hub_energy_twh'][k] for k in ['electricity','refinery_process_steam','htse_steam_and_drying','food_heat','conversion_losses_and_reject']],'TWh/year','B. Reactor thermal accounting');save(fig,'Figure_S3')
fig,(ax,bx)=plt.subplots(1,2,figsize=(10,5.5),layout='constrained');barh(ax,['Onshore wind','Solar','HTGR hubs','Offshore wind','LWR/SMR'],[r['el_supply_twh'][k] for k in ['onshore_wind','solar','htgr_hubs','offshore_wind','lwr_smr']],'TWh/year','A. Electricity supply');barh(bx,['Residues and grasses','Bamboo','Hemp','Marine seaweed','HEFA oils','Corn ethanol ATJ'],list(r['liquids_twh'].values()),'TWh/year','B. Liquid fuel routes');save(fig,'Figure_S4')
fig,ax=plt.subplots(figsize=(9,5.8),layout='constrained');barh(ax,[textwrap.fill(k.replace('_',' ').capitalize(),31) for k in r['enduse']['el']],list(r['enduse']['el'].values()),'TWh/year','Target transport electricity use');save(fig,'Figure_S5')
fig,ax=plt.subplots(figsize=(9,5),layout='constrained');barh(ax,['Digestion / capture','Asparagopsis feed','Internal gas substitution'],[w['biogas_net_avoided_mt'],w['asp_net_avoided_mt'],c['gas_credit_mt']],'Mt CO₂e/year','Target incremental mitigation');save(fig,'Figure_S6')
fig,ax=plt.subplots(figsize=(9,5.6),layout='constrained');barh(ax,[x['stream'].replace('_',' ') for x in w['streams']],[x['delivered_twh'] for x in w['streams']],'TWh/year LHV','Target biomethane by waste source');save(fig,'Figure_S7')
fig,ax=plt.subplots(figsize=(9,5),layout='constrained');barh(ax,[textwrap.fill(x['market'].split(':')[0],28) for x in r['carbon_alloc']],[x['mt'] for x in r['carbon_alloc']],'Mt solid carbon/year','Target methane-pyrolysis carbon allocation');save(fig,'Figure_S8')
fig,ax=plt.subplots(figsize=(9,5),layout='constrained');barh(ax,['Vegetables','Fish/shrimp','Grain dried','Hemp protein meal'],[r['food']['vegetables_mt'],r['food']['fish_shrimp_mt'],r['food']['grain_dried_mt'],r['food']['hemp_meal_mt']],'Mt/year','Modeled community heat-cascade products');save(fig,'Figure_S9')
fig,ax=plt.subplots(figsize=(9,5),layout='constrained');barh(ax,['External N','External P','External K','Digestate N','Digestate P','Digestate K'],[t['n_imports_kt'],t['p_imports_kt'],t['k_imports_kt'],w['digestate_N_mt']*1000,w['digestate_P_mt']*1000,w['digestate_K_mt']*1000],'Elemental kt/year','Target crop nutrient requirements and digestate potential');save(fig,'Figure_S11')
# New, current V9.19 analyses; earlier diagrams remain in their original order.
f=read('us919_frontier.csv');fig,ax=plt.subplots(figsize=(8,5),layout='constrained');xx=[float(x['progress'])*100 for x in f];yy=[float(x['break_even_bev_usd_year']) for x in f];ax.plot(xx,yy,color=C,lw=2,label='Low-petroleum break-even');ax.fill_between(xx,-500,yy,color=C,alpha=.16,label='Cost competitive');ax.scatter([75],[-300],color=B,label='Full-crop target',zorder=5);ax.axhline(-400,color=G,ls='--',label='Inherited low BEV bound');ax.set(xlabel='Progress toward inherited lower technology costs (%)',ylabel='Annual non-energy BEV differential ($/vehicle)',ylim=(-520,150),title='Technology and vehicle cost break-even frontier');ax.legend(loc='upper left',fontsize=9);ax.grid(alpha=.2);save(fig,'Figure_S18')
mc=read('us919_joint_draws.csv');fig,(ax,bx)=plt.subplots(1,2,figsize=(10,4.8),layout='constrained');ax.hist([float(x['combined_cost_bn']) for x in mc],bins=23,color=C);ax.axvline(refs[3]['ref_cost_bn'],color=O,ls='--',label='Lowest petroleum case');ax.set(xlabel='Integrated annual cost ($bn)',ylabel='Draw count',title='A. Assumed-distribution cost screen');ax.legend(fontsize=8);bx.scatter([float(x['combined_cost_bn']) for x in mc],[float(x['combined_avoided_mt'])/1000 for x in mc],s=9,alpha=.4,color=B);bx.axvline(refs[3]['ref_cost_bn'],color=O,ls='--');bx.set(xlabel='Integrated annual cost ($bn)',ylabel='Combined abatement (Gt CO₂e/year)',title='B. Cost and abatement');save(fig,'Figure_S19')
tr=read('us919_transition.csv');gate=read('us919_gated_transition.csv');fig,(ax,bx)=plt.subplots(1,2,figsize=(10,4.8),layout='constrained');for_refs=[(refs[3]['reference'],'Lowest price'),(refs[1]['reference'],'Late-2025 price'),(refs[4]['reference'],'130% price'),(refs[2]['reference'],'Higher price')]
for ref,label in for_refs:
 z=[x for x in tr if x['reference']==ref and x['reserve_peak_bn']=='10'];ax.plot([int(x['year']) for x in z],[float(x['savings_bn']) for x in z],label=label)
ax.axhline(0,color='black',lw=.7);ax.set(xlabel='Year',ylabel='Annualized saving ($bn)',title='A. Gradual adoption, $10bn reserve');ax.legend(fontsize=8);ax.grid(alpha=.2)
for profile,ready,reserve,label in [('target','2040','0','Target, 2040, no reserve'),('target','2050','0','Target, 2050, no reserve'),('strong','2040','25','Strong, 2040, $25bn reserve'),('strong','2045','25','Strong, 2045, $25bn reserve')]:
 z=[x for x in gate if x['profile']==profile and x['readiness_year']==ready and x['reserve_peak_bn']==reserve];bx.step([int(x['year']) for x in z],[100*float(x['adoption_fraction']) for x in z],where='post',label=label)
bx.set(xlabel='Year',ylabel='Adoption of fixed 2050 service (%)',title='B. No-overspend readiness gate',ylim=(-3,105));bx.legend(fontsize=8,loc='upper left');bx.grid(alpha=.2);save(fig,'Figure_S20')
fig,ax=plt.subplots(figsize=(10,5.5),layout='constrained');keys=list(r['costs_bn']);base=D['baseline_detail']['full']; labels=[textwrap.fill(k.replace('_',' ').capitalize(),31) for k in keys]; vals=[base['costs_bn'][k]-r['costs_bn'][k] for k in keys];barh(ax,labels,vals,'US$ billion/year','Cost changes versus reference-cost pathway',color=[C if v>=0 else O for v in vals]);save(fig,'Figure_S21')
print('V9.19 numerical figures generated')
